package com.springjwt.module.auth.model.response;

import java.util.List;

/**
 * Java 17+ Record Class - Modern immutable data carrier
 * Replaces traditional POJO with automatic implementations of:
 * - Constructor
 * - Getters
 * - equals()
 * - hashCode()
 * - toString()
 */
public record LoginResponse(
    String token,
    String type,
    Long id,
    String username,
    String email,
    List<String> roles
) {
    // Compact constructor with default value
    public LoginResponse(String token, Long id, String username, String email, List<String> roles) {
        this(token, "Bearer", id, username, email, roles);
    }

    // Validation in canonical constructor
    public LoginResponse {
        if (token == null || token.isBlank()) {
            throw new IllegalArgumentException("Token cannot be null or empty");
        }
        if (username == null || username.isBlank()) {
            throw new IllegalArgumentException("Username cannot be null or empty");
        }
        // Make roles immutable
        roles = roles == null ? List.of() : List.copyOf(roles);
    }
}

package com.springjwt.core.config;

import org.springframework.boot.web.embedded.tomcat.TomcatProtocolHandlerCustomizer;
import org.springframework.context.annotation.Bean;
import org.springframework.core.task.AsyncTaskExecutor;
import org.springframework.core.task.support.TaskExecutorAdapter;
import org.springframework.scheduling.annotation.EnableAsync;

import java.util.concurrent.Executors;

/**
 * Java 21+ Virtual Threads Configuration
 * 
 * IMPORTANT: This requires Java 21 or higher!
 * Virtual Threads are NOT available in Java 17.
 * 
 * To use this configuration:
 * 1. Update pom.xml: java.version to 21
 * 2. Uncomment @Configuration annotation below
 * 3. Uncomment the actual Virtual Thread executor code
 * 4. Rebuild the project
 * 
 * Virtual Threads Benefits:
 * - Lightweight: Can create millions of threads
 * - Better resource utilization
 * - Improved scalability for I/O-bound operations
 * 
 * Performance:
 * - Traditional threads: ~thousands of threads
 * - Virtual threads: ~millions of threads
 * - Memory: ~1MB per platform thread vs ~1KB per virtual thread
 */
//@Configuration
@EnableAsync
public class VirtualThreadConfig {

    /**
     * Configure Virtual Threads for @Async methods
     * Requires Java 21+
     */
    @Bean
    public AsyncTaskExecutor applicationTaskExecutor() {
        // Uncomment when using Java 21+
        // return new TaskExecutorAdapter(Executors.newVirtualThreadPerTaskExecutor());
        throw new UnsupportedOperationException("Virtual Threads require Java 21+. Please upgrade Java version.");
    }

    /**
     * Configure Virtual Threads for Tomcat request handling
     * Requires Java 21+
     */
    @Bean
    public TomcatProtocolHandlerCustomizer<?> protocolHandlerVirtualThreadExecutorCustomizer() {
        // Uncomment when using Java 21+
        // return protocolHandler -> protocolHandler.setExecutor(Executors.newVirtualThreadPerTaskExecutor());
        throw new UnsupportedOperationException("Virtual Threads require Java 21+. Please upgrade Java version.");
    }
}

